export const meta = {
  name: 'ps-research-sweep',
  description: 'Deep research: aligned real contract datasets (labelled, German, scanned/handwritten, Riverty public docs) and sourced Microsoft-vs-Gemini facts, with URL/licence verification',
  phases: [
    { title: 'Sweep', detail: '5 angles in parallel, web research' },
    { title: 'Verify', detail: 'every candidate: URL reachable, licence and content claims checked' },
  ],
}

const CONTEXT = `
Context: a case study for Riverty (German BNPL/payments company, Baden-Baden; 2022 rebrand: AfterPay and Arvato
Financial Solutions / Arvato Payment Solutions GmbH -> Riverty). We built a contract-review tool for a German legal
team: ingest PDFs (digital and scanned) and JPEG photos of old handwritten contracts; split into clauses; classify
into 12 clause types (term/termination, fees/payment, liability cap, confidentiality, data protection/GDPR,
governing law, dispute resolution, force majeure, assignment, audit rights, anti-corruption, change of control);
detect old company names; find contracts LACKING a clause/passage; verify with Gemini; human approval. So far the
corpus is synthetic (generated PDFs with known ground truth). We now need REAL, aligned input data with usable
ground truth, and sourced facts for the tech comparison. Today is 2026-08. Use web search and fetch pages; do not
guess. Return ONLY the structured result; every item must carry the URL you actually used.`

const DATASET = {
  type: 'object',
  properties: {
    candidates: { type: 'array', items: { type: 'object', properties: {
      name: { type: 'string' }, url: { type: 'string' }, download_url: { type: 'string', description: 'direct file/zip/API URL if known, else empty' },
      what: { type: 'string' }, size: { type: 'string' }, formats: { type: 'string' }, languages: { type: 'string' },
      licence: { type: 'string' }, ground_truth: { type: 'string', description: 'what labels exist and how they map to our 12 clause types / old-name task; be specific' },
      alignment: { type: 'number', description: '0-10 how aligned with our task' },
      how_to_get_subset: { type: 'string', description: 'concrete steps to obtain a small (5-30 documents) aligned subset' },
      caveats: { type: 'string' },
    }, required: ['name', 'url', 'download_url', 'what', 'size', 'formats', 'languages', 'licence', 'ground_truth', 'alignment', 'how_to_get_subset', 'caveats'] } },
    notes: { type: 'string' },
  },
  required: ['candidates', 'notes'],
}

const ANGLES = [
  { key: 'labelled-contracts', prompt: 'ANGLE: public corpora of REAL commercial contracts with expert clause annotations (e.g. CUAD from The Atticus Project, LEDGAR, ContractNLI, MAUD, ACORD, LexGLUE subsets, SEC EDGAR EX-10 material contracts). For each: what exactly is annotated (list the label categories that overlap with our 12 clause types, e.g. "Governing Law", "Cap On Liability", "Audit Rights", "Change Of Control", "Anti-Assignment", "Renewal Term"), whether ABSENCE of a category is derivable (empty answer = clause not present), file formats (PDF vs txt), licence, exact download location, and how to pull a 20-contract subset.' },
  { key: 'german-and-riverty', prompt: 'ANGLE: German-language contract sources and Riverty-specific public documents. (1) Official/institutional German contract templates as PDFs: DSK / Landesdatenschutzbehörden Muster-Auftragsverarbeitungsvertrag (AVV), IHK Musterverträge (Handelsvertretervertrag, Geheimhaltungsvereinbarung), BMWK/BMJ templates, EU Standard Contractual Clauses in German, any public German contract corpora (e.g. from Open Legal Data, GerDaLIR, Zenodo, Hugging Face). (2) Riverty public legal documents: riverty.com terms and conditions / AGB for consumers and merchants (DE and EN), privacy policies, and ARCHIVED older versions (web.archive.org) that still name "AfterPay" or "arvato Financial Solutions" / "Arvato Payment Solutions GmbH" – i.e. real documents where the old name appears, plus "formerly AfterPay" style historical references. Give exact URLs including Wayback Machine snapshot URLs.' },
  { key: 'scanned-handwritten', prompt: 'ANGLE: REAL scanned and handwritten legal/contract documents as images or image-only PDFs: the UCSF Industry Documents Library (Truth Tobacco Industry Documents – real 1960s–1990s agreements/contracts, many scanned, some handwritten; check its API and licence/terms), RVL-CDIP and Tobacco-3482 (classes incl. "handwritten", "letter", "form"), IAM handwriting database, FUNSD, SROIE, National Archives, any "historical contracts" or "scanned agreements" collections. For each: how to fetch 5–10 old scanned agreements (ideally with visible company names and signature pages), image quality, licence/terms of use, and whether any transcription ground truth exists.' },
  { key: 'microsoft-vs-gemini', prompt: 'ANGLE: sourced FACTS for a "best-of-breed vs Microsoft" comparison, 2026: (a) Azure AI Foundry model catalogue: which frontier models (OpenAI GPT-5 family, o-series, others) are available, whether Google Gemini is available in Foundry (expected: no), EU regions and data-residency/zero-retention terms; (b) Azure OpenAI / Foundry vision input for handwriting OCR vs Azure AI Document Intelligence (Read/Layout models: handwriting support, languages incl. German, price per 1,000 pages); (c) Azure AI Search (vector + hybrid + semantic ranker) pricing/tiers vs PostgreSQL Flexible Server with pgvector; (d) Google Gemini on Vertex AI: EU regions (europe-west3 Frankfurt etc.), data residency, no-training-on-customer-data terms, Gemini 3.x context window and pricing; (e) LangChain support for Azure (AzureChatOpenAI, AzureOpenAIEmbeddings) and Microsoft Graph API for SharePoint document access with delta queries (and SharePoint Premium / Syntex contract processing as the Microsoft-native alternative). Give numbers with URLs.', schema: 'facts' },
]

const FACTS = {
  type: 'object',
  properties: {
    facts: { type: 'array', items: { type: 'object', properties: { topic: { type: 'string' }, claim: { type: 'string' }, url: { type: 'string' }, date_seen: { type: 'string' }, confidence: { type: 'string', enum: ['high', 'medium', 'low'] } }, required: ['topic', 'claim', 'url', 'date_seen', 'confidence'] } },
    notes: { type: 'string' },
  },
  required: ['facts', 'notes'],
}

phase('Sweep')
const results = (await parallel(ANGLES.map((a) => () =>
  agent(`${CONTEXT}\n\n${a.prompt}`, { label: `sweep:${a.key}`, phase: 'Sweep', effort: 'high', schema: a.schema === 'facts' ? FACTS : DATASET })
    .then((r) => ({ key: a.key, result: r }))
))).filter(Boolean)
log(`sweep done: ${results.map((r) => r.key).join(', ')}`)

phase('Verify')
const VERDICT = { type: 'object', properties: { name: { type: 'string' }, url_ok: { type: 'boolean' }, licence_confirmed: { type: 'string' }, ground_truth_confirmed: { type: 'string' }, corrections: { type: 'array', items: { type: 'string' } }, keep: { type: 'boolean' } }, required: ['name', 'url_ok', 'licence_confirmed', 'ground_truth_confirmed', 'corrections', 'keep'] }
const candidates = results.filter((r) => r.key !== 'microsoft-vs-gemini').flatMap((r) => r.result.candidates.map((c) => ({ ...c, angle: r.key })))
const verified = (await parallel(candidates.slice(0, 16).map((c) => () =>
  agent(`${CONTEXT}\n\nVERIFY this dataset candidate by actually fetching its pages (WebFetch) and, where a direct download exists, checking that the URL responds. Do not trust the description; confirm or correct: URL reachable, licence text, what the labels/ground truth really are, formats, size. Say keep=false if it is not usable for us (licence forbids, dead link, no real ground truth, wrong domain).\n\nCANDIDATE:\n${JSON.stringify(c, null, 2)}`, { label: `verify:${c.name.slice(0, 24)}`, phase: 'Verify', schema: VERDICT })
))).filter(Boolean)
const facts = results.find((r) => r.key === 'microsoft-vs-gemini')?.result ?? null
return { candidates, verified, facts }

